// Vérifie la signature Linear (HMAC-SHA256 sur le corps brut de la requête,
// header `Linear-Signature`) avant de faire confiance au payload.
// Nécessite que l'option "Raw Body" soit activée sur le node Webhook en amont
// (sinon le corps re-sérialisé par n8n ne correspond plus, octet pour octet,
// à ce que Linear a signé).

const crypto = require('crypto');

const secret = $env.LINEAR_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('LINEAR_WEBHOOK_SECRET manquant dans l\'environnement n8n');
}

const item = $input.first();
const rawBodyBase64 = item.binary && item.binary.data && item.binary.data.data;
if (!rawBodyBase64) {
  throw new Error('Corps brut introuvable — vérifie que "Raw Body" est activé sur le node Webhook Linear');
}

const rawBody = Buffer.from(rawBodyBase64, 'base64');
const signatureHeader = ((item.json.headers && item.json.headers['linear-signature']) || '').toString();

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

const expectedBuf = Buffer.from(expected, 'utf8');
const receivedBuf = Buffer.from(signatureHeader, 'utf8');
const valid = expectedBuf.length === receivedBuf.length && crypto.timingSafeEqual(expectedBuf, receivedBuf);

if (!valid) {
  throw new Error('Signature Linear invalide — requête rejetée');
}

const payload = JSON.parse(rawBody.toString('utf8'));

return [{ json: payload }];

// Normalise le payload Linear (id, titre, état, labels) pour le résumé Telegram.
const body = $input.first().json;
const data = body.data || {};

const labelList = Array.isArray(data.labels)
  ? data.labels
  : (data.labels && data.labels.nodes) || [];
const labels = labelList.map((l) => (l && l.name) ? l.name : l);

return [{
  json: {
    action: body.action,
    id: data.id,
    identifier: data.identifier || data.id,
    title: data.title,
    state: (data.state && data.state.name) || 'inconnu',
    labels,
    url: data.url || ''
  }
}];
